"""Generated byte streams probe the output boundary."""

import sys

from hypothesis import given, settings, strategies as st

from autoseal.execution import CommandStatus, run_command


@settings(max_examples=35, deadline=None)
@given(
    output=st.binary(max_size=128),
    limit=st.integers(min_value=0, max_value=64),
)
def test_stdout_capture_respects_byte_limit(output: bytes, limit: int) -> None:
    script = f"import sys; sys.stdout.buffer.write({output!r})"

    result = run_command([sys.executable, "-c", script], max_output_bytes=limit)

    assert result.status is CommandStatus.EXITED_ZERO
    assert result.stdout == output[:limit].decode("utf-8", errors="replace")
    assert result.stdout_truncated is (len(output) > limit)
